insert into bullish_banana.data_verifications (firm_id,verified_at,notes)
select id,now(),'Hantec Trader official site, current seven-product USD selectors, Terms, restricted-country FAQ, leverage, platform and product-specification disclosures reviewed 2026-09-28.'
from bullish_banana.firms f where slug='hantec-trader'
and not exists(select 1 from bullish_banana.data_verifications v where v.firm_id=f.id);

insert into bullish_banana.data_verifications (program_id,verified_at,notes)
select p.id,now(),'Current official selector USD sizes/prices and model-specific support rules reviewed 2026-09-28. In review pending verification of account-specific terms/add-ons, live platform compatibility and remaining rule/locale conflicts.'
from bullish_banana.programs p join bullish_banana.firms f on f.id=p.firm_id
where f.slug='hantec-trader'
